/** Suite SEO nativa: ajustes, editor, metadatos, schema, social, sitemap y diagnóstico. */
class Digitalisimo_Integrations_SEO_Suite {
	const P = 'digitalisimo_seo_';
	public static function init() {
		if ( ! Digitalisimo_Integrations_Settings::get( 'enable_seo' ) ) return;
		add_action( 'admin_menu', array( __CLASS__, 'menu' ), 25 );
		add_action( 'add_meta_boxes', array( __CLASS__, 'metaboxes' ) ); add_action( 'save_post', array( __CLASS__, 'save_post' ), 15 ); add_action( 'wp_after_insert_post', array( __CLASS__, 'ensure_post_author' ), 15, 4 ); add_filter( 'wp_get_attachment_image_attributes', array( __CLASS__, 'attachment_alt' ), 20, 3 );
		add_action( 'admin_enqueue_scripts', array( __CLASS__, 'editor_assets' ) );
		// El editor de snippet es el panel principal de SEO: nunca debe quedar
		// perdido por una preferencia heredada del usuario en Gutenberg.
		add_filter( 'hidden_meta_boxes', array( __CLASS__, 'keep_snippet_visible' ), 10, 2 );
		add_action( 'init', array( __CLASS__, 'taxonomies' ) ); add_action( 'created_term', array( __CLASS__, 'save_term' ), 10, 3 ); add_action( 'edited_term', array( __CLASS__, 'save_term' ), 10, 3 );
		remove_action( 'wp_head', 'rel_canonical' ); add_filter( 'pre_get_document_title', array( __CLASS__, 'title' ), 20 ); add_action( 'wp_head', array( __CLASS__, 'mobile_horizontal_scroll_css' ), 0 ); add_action( 'wp_head', array( __CLASS__, 'head' ), 1 ); add_action( 'wp_head', array( __CLASS__, 'content_location_schema' ), 2 ); add_filter( 'wp_robots', array( __CLASS__, 'robots' ) );
		add_filter( 'wp_sitemaps_enabled', array( __CLASS__, 'sitemap_enabled' ) ); add_filter( 'wp_sitemaps_post_types', array( __CLASS__, 'sitemap_posts' ) ); add_filter( 'wp_sitemaps_taxonomies', array( __CLASS__, 'sitemap_terms' ) ); add_filter( 'wp_sitemaps_posts_query_args', array( __CLASS__, 'sitemap_query' ), 10, 2 );
		add_action( 'template_redirect', array( __CLASS__, 'attachment_redirect' ) ); add_shortcode( 'digitalisimo_breadcrumbs', array( __CLASS__, 'breadcrumb_shortcode' ) );
		if ( is_multisite() ) { add_action( 'network_admin_edit_digitalisimo_save_network_seo', array( __CLASS__, 'save_network' ) ); add_action( 'admin_post_digitalisimo_clone_site', array( __CLASS__, 'create_clone' ) ); add_action( 'digitalisimo_seo_clone_site', array( __CLASS__, 'run_clone' ) ); add_filter( 'manage_sites_action_links', array( __CLASS__, 'site_clone_action' ), 20, 3 ); }
	}
	private static function o( $key, $default = '' ) { return Digitalisimo_Integrations_Settings::get( $key, $default ); }
