	/** Referencia visible para las plantillas de títulos y descripciones. */
	private static function template_variables_help() {
		echo '<tr><th colspan="2"><h2>Variables disponibles</h2><p class="description">Puedes combinarlas en títulos y descripciones. Cada variable se sustituye al mostrar la página pública.</p><ul class="digitalisimo-template-variables"><li><code>%title%</code> Título del contenido, página o archivo actual.</li><li><code>%sitename%</code> Nombre SEO configurado para este sitio; si no existe, el nombre de WordPress.</li><li><code>%sep%</code> Separador de títulos configurado en Identidad.</li><li><code>%excerpt%</code> Extracto del contenido; si no hay extracto, usa el resumen disponible.</li><li><code>%term%</code> Nombre de la categoría, etiqueta u otro término que se está consultando.</li><li><code>%description%</code> Descripción del término o archivo actual.</li><li><code>%page%</code> Número de página de la paginación, sólo cuando aplica.</li></ul></th></tr>';
	}
	/** Conserva el alt propio de Biblioteca y usa la plantilla sólo como respaldo al renderizar. */
	public static function attachment_alt( $attributes, $attachment, $size ) { if ( ! empty( trim( (string) ( $attributes['alt'] ?? '' ) ) ) ) return $attributes; $template = trim( (string) self::o( 'seo_default_image_alt' ) ); if ( ! $template ) return $attributes; $attachment_id = is_object( $attachment ) ? absint( $attachment->ID ?? 0 ) : absint( $attachment ); $content_id = get_queried_object_id(); $content = $content_id ? get_post( $content_id ) : null; $image = $attachment_id ? get_post( $attachment_id ) : null; $post_type = $content ? get_post_type_object( $content->post_type ) : null; $keywords = $content_id ? array_filter( array_map( 'trim', explode( ',', (string) get_post_meta( $content_id, self::P . 'keywords', true ) ) ) ) : array(); $file = $attachment_id ? get_attached_file( $attachment_id ) : ''; $alt = strtr( $template, array( '%title%' => $content ? $content->post_title : '', '%excerpt%' => $content ? ( $content->post_excerpt ?: wp_trim_words( wp_strip_all_tags( $content->post_content ), 30, '' ) ) : '', '%keyword%' => $keywords[0] ?? '', '%author%' => $content ? get_the_author_meta( 'display_name', $content->post_author ) : '', '%post_type%' => $post_type ? $post_type->labels->singular_name : '', '%sitename%' => get_bloginfo( 'name' ), '%site_description%' => get_bloginfo( 'description' ), '%sep%' => self::o( 'seo_separator' ) ?: '|', '%image_title%' => $image ? $image->post_title : '', '%image_caption%' => $image ? $image->post_excerpt : '', '%image_description%' => $image ? $image->post_content : '', '%image_filename%' => $file ? wp_basename( $file ) : '' ) ); $alt = wp_html_excerpt( trim( wp_strip_all_tags( $alt ) ), 250, '' ); if ( $alt ) $attributes['alt'] = $alt; return $attributes; }
	/** WordPress conserva el autor asignado; sólo rellena publicaciones nuevas que lleguen sin autor. */
	public static function ensure_post_author( $post_id, $post, $update, $post_before ) { if ( $update || ! $post || ! in_array( $post->post_type, self::editable_types(), true ) || absint( $post->post_author ) || ! get_current_user_id() ) return; remove_action( 'wp_after_insert_post', array( __CLASS__, 'ensure_post_author' ), 15 ); wp_update_post( array( 'ID' => $post_id, 'post_author' => get_current_user_id() ) ); add_action( 'wp_after_insert_post', array( __CLASS__, 'ensure_post_author' ), 15, 4 ); }
	private static function list_value( $key ) { return array_filter( array_map( 'sanitize_key', array_map( 'trim', explode( ',', (string) self::o( $key ) ) ) ) ); }
	private static function editable_types() { return get_post_types( array( 'public' => true, 'show_ui' => true ), 'names' ); }
