		foreach ( $advanced as $slug ) add_submenu_page( null, 'SEO', 'SEO', 'manage_options', $slug, array( __CLASS__, 'page' ) );
		$editorial = array( 'digitalisimo-content' => array( 'Contenido', 'content_page' ), 'digitalisimo-keywords' => array( 'Keywords', 'keywords_page' ), 'digitalisimo-clusters' => array( 'Clusters', 'clusters_page' ), 'digitalisimo-intents' => array( 'Intención SEO', 'intents_page' ) );
		foreach ( $editorial as $slug => $page ) add_submenu_page( null, $page[0], $page[0], 'manage_options', $slug, array( 'Digitalisimo_Integrations_SEO', $page[1] ) );
	}
