		echo '<h2 class="nav-tab-wrapper digitalisimo-tabs">'; foreach ( self::navigation_items() as $tab => $label ) { $target = 'dashboard' === $tab ? 'digitalisimo-seo' : ( 'content' === $tab ? 'digitalisimo-content' : 'digitalisimo-seo-' . $tab ); $url = $network ? network_admin_url( 'admin.php?page=digitalisimo-network-seo&tab=' . $tab ) : admin_url( 'admin.php?page=' . $target ); echo '<a class="nav-tab ' . ( $active === $tab ? 'nav-tab-active' : '' ) . '"' . ( $network ? ' data-tab="' . esc_attr( $tab ) . '"' : '' ) . ' href="' . esc_url( $url ) . '">' . esc_html( $label ) . '</a>'; } echo '</h2>';
	}
	public static function network_menu() { add_menu_page( 'Digitalisimo', 'Digitalisimo', 'manage_network_options', 'digitalisimo-network-seo', array( __CLASS__, 'network_page' ), 'dashicons-chart-line', 56 ); add_submenu_page( 'digitalisimo-network-seo', 'SEO', 'SEO', 'manage_network_options', 'digitalisimo-network-seo', array( __CLASS__, 'network_page' ) ); add_submenu_page( 'digitalisimo-network-seo', 'Clonar sitio', 'Clonar sitio', 'manage_network_options', 'digitalisimo-network-seo-clone', array( __CLASS__, 'clone_page' ) ); }
	/** Enlace contextual en Red → Sitios; sólo lo ven los superadministradores. */
	public static function site_clone_action( $actions, $site_id, $blogname = '' ) { $site_id = absint( $site_id ); if ( ! is_network_admin() || ! current_user_can( 'manage_network_options' ) || ! is_super_admin() || ! $site_id ) return $actions; $actions['digitalisimo_clone'] = '<a href="' . esc_url( add_query_arg( array( 'page' => 'digitalisimo-network-seo-clone', 'source_site' => $site_id ), network_admin_url( 'admin.php' ) ) ) . '">Duplicar</a>'; return $actions; }
	/** La clonación sólo existe en el administrador de red y nunca se expone dentro de un sitio. */
	public static function clone_page() {
		if ( ! is_multisite() || ! is_network_admin() || ! current_user_can( 'manage_network_options' ) || ! is_super_admin() ) return;
		$sites = get_sites( array( 'number' => 0, 'orderby' => 'domain', 'order' => 'ASC' ) ); $selected_source = absint( $_GET['source_site'] ?? 0 ); $status = sanitize_key( $_GET['clone_status'] ?? '' );
		echo '<div class="wrap digitalisimo-admin-shell"><h1>Clonar sitio</h1><p>Copia un sitio completo de esta red para usarlo como nueva base SEO. Incluye contenido, medios, tema, Elementor, opciones, configuración SEO y permisos del sitio origen. El destino permanece privado hasta terminar la copia.</p>';
		if ( 'queued' === $status ) echo '<div class="notice notice-info"><p>El clon se creó y la copia quedó programada. Recarga esta pantalla para ver su estado.</p></div>'; elseif ( 'complete' === $status ) echo '<div class="notice notice-success"><p>La clonación terminó correctamente.</p></div>'; elseif ( 'error' === $status ) echo '<div class="notice notice-error"><p>No fue posible completar la clonación. Revisa el estado mostrado abajo.</p></div>';
		echo '<form method="post" action="' . esc_url( admin_url( 'admin-post.php' ) ) . '"><input type="hidden" name="action" value="digitalisimo_clone_site">'; wp_nonce_field( 'digitalisimo_clone_site' ); echo '<table class="form-table"><tr><th><label for="digitalisimo_clone_source">Sitio origen</label></th><td><select id="digitalisimo_clone_source" name="source_site" required>'; foreach ( $sites as $site ) echo '<option value="' . esc_attr( $site->blog_id ) . '" ' . selected( $selected_source, $site->blog_id, false ) . '>' . esc_html( get_site_url( $site->blog_id, '/' ) . ' · ' . get_blog_option( $site->blog_id, 'blogname' ) ) . '</option>'; echo '</select></td></tr><tr><th><label for="digitalisimo_clone_url">Nueva URL o subdominio</label></th><td><input class="regular-text" id="digitalisimo_clone_url" name="destination" required placeholder="https://nuevo.ejemplo.com/ o nuevo"><p class="description">Usa una URL completa. También puedes escribir sólo un subdominio si la red está configurada por subdominios.</p></td></tr><tr><th>Confirmación</th><td><label><input type="checkbox" name="confirm" value="1" required> Entiendo que se copiará todo el sitio origen al destino.</label></td></tr></table>'; submit_button( 'Crear clon del sitio', 'primary', 'submit', false ); echo '</form>';
		$jobs = (array) get_site_option( 'digitalisimo_seo_clone_jobs', array() ); if ( $jobs ) { echo '<h2>Clonaciones recientes</h2><table class="widefat striped"><thead><tr><th>Destino</th><th>Origen</th><th>Estado</th><th>Detalle</th></tr></thead><tbody>'; foreach ( array_reverse( $jobs, true ) as $job ) echo '<tr><td>' . esc_html( $job['destination'] ?? '' ) . '</td><td>' . esc_html( $job['source_url'] ?? '' ) . '</td><td>' . esc_html( $job['status'] ?? '' ) . '</td><td>' . esc_html( $job['message'] ?? '' ) . '</td></tr>'; echo '</tbody></table>'; }
		echo '</div>';
	}
	private static function clone_destination( $raw ) {
		$raw = trim( (string) $raw ); if ( ! $raw ) return new WP_Error( 'digitalisimo_clone_url', 'Escribe la nueva URL o subdominio.' );
		if ( false === strpos( $raw, '://' ) ) { if ( false === strpos( $raw, '.' ) && is_subdomain_install() ) { $network = get_network(); $raw .= '.' . $network->domain; } $raw = 'https://' . $raw; }
		$parts = wp_parse_url( $raw ); $domain = strtolower( $parts['host'] ?? '' ); $path = '/' . trim( (string) ( $parts['path'] ?? '' ), '/' ) . '/'; if ( '/' === $path ) $path = '/';
		if ( ! $domain || ! preg_match( '/^[a-z0-9.-]+$/', $domain ) ) return new WP_Error( 'digitalisimo_clone_url', 'La URL de destino no es válida.' );
		return array( 'domain' => $domain, 'path' => $path );
	}
	public static function create_clone() {
		if ( ! is_multisite() || ! current_user_can( 'manage_network_options' ) || ! is_super_admin() || ! check_admin_referer( 'digitalisimo_clone_site' ) ) wp_die( 'No autorizado.' );
		$source_id = absint( $_POST['source_site'] ?? 0 ); $source = get_site( $source_id ); $destination = self::clone_destination( wp_unslash( $_POST['destination'] ?? '' ) );
		if ( ! $source || is_wp_error( $destination ) || empty( $_POST['confirm'] ) ) { wp_safe_redirect( add_query_arg( array( 'page' => 'digitalisimo-network-seo-clone', 'clone_status' => 'error' ), network_admin_url( 'admin.php' ) ) ); exit; }
		if ( get_site_by_path( $destination['domain'], $destination['path'], 1 ) ) { wp_safe_redirect( add_query_arg( array( 'page' => 'digitalisimo-network-seo-clone', 'clone_status' => 'error' ), network_admin_url( 'admin.php' ) ) ); exit; }
		$title = get_blog_option( $source_id, 'blogname', $source->domain ); $target_id = wpmu_create_blog( $destination['domain'], $destination['path'], $title, get_current_user_id(), array( 'public' => 0 ), get_current_network_id() );
		if ( is_wp_error( $target_id ) ) { wp_safe_redirect( add_query_arg( array( 'page' => 'digitalisimo-network-seo-clone', 'clone_status' => 'error' ), network_admin_url( 'admin.php' ) ) ); exit; }
		$jobs = (array) get_site_option( 'digitalisimo_seo_clone_jobs', array() ); $jobs[ $target_id ] = array( 'source_id' => $source_id, 'source_url' => get_site_url( $source_id, '/' ), 'destination' => get_site_url( $target_id, '/' ), 'status' => 'queued', 'message' => 'Esperando la tarea de clonación.', 'created' => time() ); update_site_option( 'digitalisimo_seo_clone_jobs', $jobs ); wp_schedule_single_event( time() + 5, 'digitalisimo_seo_clone_site', array( $target_id ) ); spawn_cron(); wp_safe_redirect( add_query_arg( array( 'page' => 'digitalisimo-network-seo-clone', 'clone_status' => 'queued' ), network_admin_url( 'admin.php' ) ) ); exit;
	}
	private static function clone_tables( $source_id ) { global $wpdb; $prefix = $wpdb->get_blog_prefix( $source_id ); $like = $wpdb->esc_like( $prefix ) . '%'; $tables = $wpdb->get_col( $wpdb->prepare( 'SHOW TABLES LIKE %s', $like ) ); if ( 1 === (int) $source_id ) $tables = array_filter( $tables, function( $table ) use ( $prefix ) { return ! preg_match( '/^' . preg_quote( $prefix, '/' ) . '[0-9]+_/', $table ); } ); return array_values( $tables ); }
	private static function clone_replace_value( $value, $replacements ) { if ( ! is_string( $value ) || '' === $value ) return $value; if ( is_serialized( $value ) ) { $unserialized = maybe_unserialize( $value ); $walk = function( $item ) use ( &$walk, $replacements ) { if ( is_array( $item ) ) { foreach ( $item as $key => $value ) $item[ $key ] = $walk( $value ); return $item; } if ( is_object( $item ) ) { foreach ( get_object_vars( $item ) as $key => $value ) $item->$key = $walk( $value ); return $item; } return is_string( $item ) ? strtr( $item, $replacements ) : $item; }; return serialize( $walk( $unserialized ) ); } return strtr( $value, $replacements ); }
	private static function clone_members( $source_id, $target_id ) { global $wpdb; $source_prefix = $wpdb->get_blog_prefix( $source_id ); $target_prefix = $wpdb->get_blog_prefix( $target_id ); foreach ( array( 'capabilities', 'user_level' ) as $suffix ) { $rows = $wpdb->get_results( $wpdb->prepare( "SELECT user_id, meta_value FROM {$wpdb->usermeta} WHERE meta_key = %s", $source_prefix . $suffix ), ARRAY_A ); foreach ( $rows as $row ) update_user_meta( $row['user_id'], $target_prefix . $suffix, maybe_unserialize( $row['meta_value'] ) ); } }
	/** Copia tablas con prefijo del sitio, archivos de uploads y referencias URL, sin tocar tablas globales de la red. */
	public static function run_clone( $target_id ) {
		global $wpdb; $target_id = absint( $target_id ); $jobs = (array) get_site_option( 'digitalisimo_seo_clone_jobs', array() ); $job = $jobs[ $target_id ] ?? null; if ( ! $job || 'queued' !== $job['status'] ) return; $source_id = absint( $job['source_id'] ?? 0 ); if ( ! get_site( $source_id ) || ! get_site( $target_id ) ) return;
		$jobs[ $target_id ]['status'] = 'running'; $jobs[ $target_id ]['message'] = 'Copiando tablas, medios y configuración.'; update_site_option( 'digitalisimo_seo_clone_jobs', $jobs );
		try {
			$source_prefix = $wpdb->get_blog_prefix( $source_id ); $target_prefix = $wpdb->get_blog_prefix( $target_id ); $old_url = get_site_url( $source_id, '/' ); $new_url = get_site_url( $target_id, '/' );
			switch_to_blog( $source_id ); $source_uploads = wp_upload_dir(); restore_current_blog(); switch_to_blog( $target_id ); $target_uploads = wp_upload_dir(); restore_current_blog();
			$replacements = array( untrailingslashit( $source_uploads['baseurl'] ) => untrailingslashit( $target_uploads['baseurl'] ), untrailingslashit( $old_url ) => untrailingslashit( $new_url ) ); uksort( $replacements, function( $a, $b ) { return strlen( $b ) <=> strlen( $a ); } );
			foreach ( self::clone_tables( $source_id ) as $source_table ) { $suffix = substr( $source_table, strlen( $source_prefix ) ); $target_table = $target_prefix . $suffix; $wpdb->query( "DROP TABLE IF EXISTS `{$target_table}`" ); if ( false === $wpdb->query( "CREATE TABLE `{$target_table}` LIKE `{$source_table}`" ) ) throw new Exception( 'No se pudo crear la tabla ' . $suffix . '.' ); $columns = $wpdb->get_results( "SHOW COLUMNS FROM `{$source_table}`", ARRAY_A ); $text_columns = array(); foreach ( $columns as $column ) if ( preg_match( '/char|text|json/i', $column['Type'] ) ) $text_columns[] = $column['Field']; $rows = $wpdb->get_results( "SELECT * FROM `{$source_table}`", ARRAY_A ); foreach ( $rows as $row ) { foreach ( $text_columns as $column ) if ( array_key_exists( $column, $row ) ) $row[ $column ] = self::clone_replace_value( $row[ $column ], $replacements ); if ( false === $wpdb->insert( $target_table, $row ) ) throw new Exception( 'No se pudo copiar datos de ' . $suffix . '.' ); } }
			$wpdb->query( $wpdb->prepare( "UPDATE `{$target_prefix}options` SET option_name = REPLACE(option_name, %s, %s) WHERE option_name LIKE %s", $source_prefix, $target_prefix, $wpdb->esc_like( $source_prefix ) . '%' ) ); self::clone_members( $source_id, $target_id );
			if ( is_dir( $source_uploads['basedir'] ) ) { require_once ABSPATH . 'wp-admin/includes/file.php'; wp_mkdir_p( $target_uploads['basedir'] ); $copied = copy_dir( $source_uploads['basedir'], $target_uploads['basedir'] ); if ( is_wp_error( $copied ) ) throw new Exception( $copied->get_error_message() ); }
			$source_site = get_site( $source_id ); update_blog_status( $target_id, 'public', (int) $source_site->public ); clean_blog_cache( $target_id ); $jobs[ $target_id ]['status'] = 'complete'; $jobs[ $target_id ]['message'] = 'Sitio clonado correctamente.';
		} catch ( Throwable $error ) { $jobs[ $target_id ]['status'] = 'error'; $jobs[ $target_id ]['message'] = $error->getMessage(); update_blog_status( $target_id, 'public', 0 ); }
		update_site_option( 'digitalisimo_seo_clone_jobs', $jobs );
	}
	public static function network_page() {
