	public static function save_network() { if ( ! is_multisite() || ! current_user_can( 'manage_network_options' ) || ! is_super_admin() || ! check_admin_referer( 'digitalisimo_network_seo' ) ) wp_die( 'No autorizado.' ); $input = (array) wp_unslash( $_POST['digitalisimo_network'] ?? array() ); $current = (array) get_site_option( Digitalisimo_Integrations_Settings::OPTION, array() ); $checkboxes = array( 'enable_seo', 'enable_woocommerce', 'enable_ipinfo', 'keyword_auto_from_title', 'seo_local_enabled', 'seo_schema_enabled', 'seo_open_graph', 'seo_twitter_enabled', 'seo_breadcrumbs', 'sitemap_enabled', 'seo_redirect_attachments', 'seo_mobile_prevent_horizontal_scroll', 'noindex_search', 'noindex_authors', 'noindex_empty_tags', 'noindex_date_archives', 'noindex_attachments', 'noindex_elementor', 'noindex_woo_pages', 'require_domain_hosting', 'replace_hosting', 'simplify_checkout', 'perf_safe_mode', 'perf_gutenberg', 'perf_emojis', 'perf_embeds', 'perf_dashicons', 'perf_font_swap', 'perf_css_defer', 'perf_caption_normal', 'perf_tracking_enabled' ); foreach ( $input as $key => $value ) { if ( ! array_key_exists( $key, Digitalisimo_Integrations_Settings::defaults() ) || in_array( $key, Digitalisimo_Integrations_SEO_Resolver::site_only_keys(), true ) ) continue; if ( in_array( $key, $checkboxes, true ) ) { $current[ $key ] = empty( $value ) ? 0 : 1; continue; } // Un secreto vacío conserva el valor almacenado en lugar de borrarlo.
			if ( 'keyword_max_count' === $key ) { $current[ $key ] = min( 5, max( 1, absint( $value ) ) ); continue; }
			if ( 'default_cluster_pillar' === $key ) { $pillar = Digitalisimo_Integrations_Editorial::cluster_candidate_id( $value ); $current[ $key ] = $pillar ? get_post_field( 'post_name', $pillar ) : ''; continue; }
			if ( in_array( $key, Digitalisimo_Integrations_Settings::template_default_keys(), true ) && '' === trim( (string) $value ) ) { $defaults = Digitalisimo_Integrations_Settings::defaults(); $current[ $key ] = $defaults[ $key ]; continue; }
			if ( in_array( $key, self::secret_keys(), true ) && '' === trim( (string) $value ) ) continue; // La ruta de acceso necesita su propia validación: un valor reservado dejaría la red sin escritorio.
			if ( Digitalisimo_Integrations_Hide_Login::KEY === $key ) { $current[ $key ] = Digitalisimo_Integrations_Hide_Login::sanitize_slug( $value ); continue; }
			if ( 'seo_default_image_alt' === $key ) { $current[ $key ] = sanitize_text_field( $value ); continue; }
			if ( 'perf_css_defer_handles' === $key ) { $current[ $key ] = Digitalisimo_Integrations_Performance_CSS::sanitize_handles( $value ); continue; }
			if ( 'perf_custom_css' === $key ) { $current[ $key ] = Digitalisimo_Integrations_Performance_CSS::sanitize_custom_css( $value ); continue; }
			if ( 'perf_font_guard_mode' === $key ) { $current[ $key ] = Digitalisimo_Integrations_Performance_Font_Guard::sanitize_mode( $value ); continue; }
			if ( 'perf_font_guard_allowlist' === $key ) { $current[ $key ] = Digitalisimo_Integrations_Performance_Font_Guard::sanitize_allowlist( $value ); continue; }
			if ( 'perf_preload_mode' === $key ) { $current[ $key ] = Digitalisimo_Integrations_Performance_Preloads::sanitize_mode( $value ); continue; }
			if ( 'perf_preload_paths' === $key ) { $current[ $key ] = Digitalisimo_Integrations_Performance_Preloads::sanitize_paths( $value ); continue; }
			if ( 'perf_preload_limit' === $key ) { $current[ $key ] = Digitalisimo_Integrations_Performance_Preloads::sanitize_limit( $value ); continue; }
			if ( in_array( $key, array( 'perf_gt_id', 'perf_ga4_id', 'perf_gtm_id' ), true ) ) { $kind = array( 'perf_gt_id' => 'gt', 'perf_ga4_id' => 'ga4', 'perf_gtm_id' => 'gtm' ); $current[ $key ] = Digitalisimo_Integrations_Performance_Tracking::sanitize_id( $value, $kind[ $key ] ); continue; }
			if ( 'perf_tracking_mode' === $key ) { $current[ $key ] = Digitalisimo_Integrations_Performance_Tracking::sanitize_mode( $value ); continue; }
			if ( in_array( $key, array( 'perf_tracking_delay', 'perf_tracking_fallback' ), true ) ) { $current[ $key ] = Digitalisimo_Integrations_Performance_Tracking::sanitize_seconds( $value ); continue; }
			// Las URLs de archivo se guardan como URL, no como texto plano.
			if ( in_array( $key, self::media_keys(), true ) ) { $current[ $key ] = esc_url_raw( trim( (string) $value ) ); continue; }
			if ( Digitalisimo_Integrations_Social_Profiles::KEY === $key ) { $current[ $key ] = Digitalisimo_Integrations_Social_Profiles::sanitize( $value, $current[ $key ] ?? array() ); continue; }
			if ( Digitalisimo_Integrations_Social_Profiles::LEGACY === $key ) { $current[ $key ] = Digitalisimo_Integrations_Social_Profiles::sanitize_extras( $value ); continue; }
			if ( Digitalisimo_Integrations_Local_Business::SCHEDULE === $key ) { $current[ $key ] = Digitalisimo_Integrations_Local_Business::sanitize_schedule( $value ); continue; }
			if ( Digitalisimo_Integrations_Local_Business::PHONE_CC === $key ) { $current[ $key ] = Digitalisimo_Integrations_Local_Business::sanitize_code( $value ); continue; }
			if ( Digitalisimo_Integrations_Local_Business::PHONE === $key ) { $current[ $key ] = Digitalisimo_Integrations_Local_Business::sanitize_phone( $value ); continue; }
			$current[ $key ] = sanitize_textarea_field( $value ); }
		update_site_option( Digitalisimo_Integrations_Settings::OPTION, $current );
		$return = sanitize_key( $_POST['digitalisimo_return'] ?? '' );
		$performance = in_array( $return, array( 'css', 'fonts', 'tracking', 'preloads' ), true );
		$target = $performance ? network_admin_url( 'admin.php?page=digitalisimo-network-performance&section=' . $return . '&updated=1' ) : network_admin_url( 'admin.php?page=digitalisimo-network-seo&updated=1&tab=' . sanitize_key( $_POST['digitalisimo_active_tab'] ?? 'general' ) );
		$site_id = $performance ? absint( $_POST['digitalisimo_site_id'] ?? 0 ) : 0;
		if ( $site_id && get_site( $site_id ) ) $target = add_query_arg( 'site_id', $site_id, $target );
		wp_safe_redirect( $target );
		exit;
	}
	public static function page() {
		if ( ! current_user_can( 'manage_options' ) ) return; $slug = sanitize_key( $_GET['page'] ?? 'digitalisimo-seo' ); $map = array( 'digitalisimo-seo' => 'dashboard', 'digitalisimo-seo-general' => 'general', 'digitalisimo-seo-titles' => 'titles', 'digitalisimo-seo-appearance' => 'appearance', 'digitalisimo-seo-schema' => 'schema', 'digitalisimo-seo-local' => 'local', 'digitalisimo-seo-social' => 'social', 'digitalisimo-seo-sitemap' => 'sitemap', 'digitalisimo-seo-indexing' => 'indexing', 'digitalisimo-seo-breadcrumbs' => 'breadcrumbs', 'digitalisimo-seo-performance' => 'performance', 'digitalisimo-seo-tools' => 'tools', 'digitalisimo-seo-diagnostic' => 'diagnostic' ); $section = $map[ $slug ] ?? 'dashboard';
		echo '<div class="wrap digitalisimo-admin-shell"><h1>SEO · Digitalisimo</h1><p>Configura las señales SEO del sitio desde un solo lugar.</p>'; self::navigation_tabs( $section );
		if ( 'dashboard' === $section ) { self::dashboard(); echo '</div>'; return; } if ( 'diagnostic' === $section ) { self::diagnostic(); echo '</div>'; return; } if ( 'tools' === $section ) { self::tools(); echo '</div>'; return; }
		if ( 'performance' === $section ) echo '<p>Optimización contextual y reversible. En modo seguro no se retiran recursos centrales de Elementor, Swiper ni WooCommerce.</p>';
		echo '<form method="post" action="options.php">'; settings_fields( 'digitalisimo_integrations' ); echo '<table class="form-table" role="presentation">'; self::settings_fields( $section ); echo '</table>'; submit_button( 'Guardar cambios SEO' ); echo '</form>'; if ( 'performance' === $section ) { Digitalisimo_Integrations_Asset_Diagnostics::render(); Digitalisimo_Integrations_Performance_Measurements::render(); Digitalisimo_Integrations_Performance_Manager::render_log(); } echo '<script>document.querySelectorAll(".digitalisimo-network-inherit").forEach(function(c){var f=document.getElementById(c.dataset.field);function s(){if(f)f.disabled=c.checked;}c.addEventListener("change",s);s();});</script></div>';
	}
	private static function f( $key, $label, $type = 'text', $help = '' ) {
		$value = self::o( $key ); $name = Digitalisimo_Integrations_Settings::OPTION . '[' . $key . ']';
		$site_only = in_array( $key, Digitalisimo_Integrations_SEO_Resolver::site_only_keys(), true );
		$inherit = is_multisite() && Digitalisimo_Integrations_SEO_Resolver::inherits_network( $key ); $disabled = $inherit ? ' disabled' : '';
		$defaults = Digitalisimo_Integrations_Settings::defaults(); $is_default = ! $inherit && array_key_exists( $key, $defaults ) && $value == $defaults[ $key ];
		$class = 'digitalisimo-inheritable' . ( $inherit ? ' digitalisimo-inherited-value' : ( $is_default ? ' digitalisimo-default-value' : '' ) );
		echo '<tr><th scope="row"><label for="' . esc_attr( $key ) . '">' . esc_html( $label ) . '</label></th><td>';
		if ( 'checkbox' === $type ) echo '<input type="hidden" name="' . esc_attr( $name ) . '" value="0"><label><input class="' . esc_attr( $class ) . '" type="checkbox" id="' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '" value="1" ' . checked( $value, 1, false ) . $disabled . '> Activar</label>';
		elseif ( 'textarea' === $type ) echo '<textarea class="large-text ' . esc_attr( $class ) . '" rows="4" id="' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '"' . $disabled . '>' . esc_textarea( $value ) . '</textarea>';
		elseif ( 'media' === $type ) Digitalisimo_Media_Field::render( $key, $name, $value, (bool) $inherit, $class );
		elseif ( 'select' === $type ) { $choices = func_get_arg( 4 ); echo '<select class="' . esc_attr( $class ) . '" id="' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '"' . $disabled . '>'; foreach ( (array) $choices as $v => $l ) echo '<option value="' . esc_attr( $v ) . '" ' . selected( $value, $v, false ) . '>' . esc_html( $l ) . '</option>'; echo '</select>'; }
		else echo '<input class="regular-text ' . esc_attr( $class ) . '" type="' . esc_attr( $type ) . '" id="' . esc_attr( $key ) . '" name="' . esc_attr( $name ) . '" value="' . esc_attr( $value ) . '"' . $disabled . '>';
		if ( $help ) echo '<p class="description">' . esc_html( $help ) . '</p>';
		if ( $is_default ) echo '<p class="description digitalisimo-default-note">Valor predeterminado del plugin.</p>';
		if ( is_multisite() && ! $site_only ) { $origin = Digitalisimo_Integrations_SEO_Resolver::option_with_origin( $key ); echo '<p class="digitalisimo-inheritance"><input type="hidden" name="' . esc_attr( Digitalisimo_Integrations_Settings::OPTION ) . '[network_inherit][' . esc_attr( $key ) . ']" value="0"><label><input class="digitalisimo-network-inherit" data-field="' . esc_attr( $key ) . '" type="checkbox" name="' . esc_attr( Digitalisimo_Integrations_Settings::OPTION ) . '[network_inherit][' . esc_attr( $key ) . ']" value="1" ' . checked( $inherit, true, false ) . '> Heredar de la red</label><br><span class="description">Valor efectivo: <strong>' . esc_html( is_scalar( $origin['value'] ) ? (string) $origin['value'] : '' ) . '</strong> · Origen: ' . esc_html( $origin['label'] ) . '</span></p>'; }
		echo '</td></tr>';
	}
