	private static function dashboard() { $types = self::editable_types(); $published = count( get_posts( array( 'post_type' => $types, 'post_status' => 'publish', 'posts_per_page' => -1, 'fields' => 'ids' ) ) ); $noindex = count( get_posts( array( 'post_type' => $types, 'posts_per_page' => -1, 'fields' => 'ids', 'meta_key' => self::P . 'robots', 'meta_value' => 'noindex', 'compare' => 'LIKE' ) ) ); $keywords = count( get_posts( array( 'post_type' => $types, 'posts_per_page' => -1, 'fields' => 'ids', 'meta_key' => self::P . 'keywords', 'compare' => 'EXISTS' ) ) ); echo '<p>Configuración SEO nativa por sitio. En Multisite, cada subsitio conserva sus propios valores.</p><div class="notice notice-info inline"><p><strong>Sitemap:</strong> <a href="' . esc_url( home_url( '/wp-sitemap.xml' ) ) . '" target="_blank" rel="noopener">' . esc_html( home_url( '/wp-sitemap.xml' ) ) . '</a></p></div><table class="widefat striped"><tr><th>Contenidos publicados</th><td>' . esc_html( $published ) . '</td></tr><tr><th>Con keywords</th><td>' . esc_html( $keywords ) . '</td></tr><tr><th>Noindex editorial</th><td>' . esc_html( $noindex ) . '</td></tr><tr><th>Schema</th><td>' . ( self::o( 'seo_schema_enabled' ) ? 'Activo' : 'Inactivo' ) . '</td></tr></table>'; }
	private static function diagnostic() { Digitalisimo_Integrations_SEO_Front_Inspector::render(); }
	private static function tools() { echo '<h2>SEO · Avanzado</h2><p>Estas opciones son técnicas. La configuración habitual se realiza desde Identidad y visibilidad, Estrategia de contenido y el editor de cada contenido.</p><p><a class="button button-secondary" href="' . esc_url( home_url( '/wp-sitemap.xml' ) ) . '" target="_blank" rel="noopener">Ver sitemap XML</a> <a class="button button-secondary" href="' . esc_url( home_url( '/robots.txt' ) ) . '" target="_blank" rel="noopener">Ver robots.txt</a></p><h3>Optimización móvil</h3><form method="post" action="options.php"><input type="hidden" name="digitalisimo_integrations_options[seo_mobile_prevent_horizontal_scroll]" value="0">'; settings_fields( 'digitalisimo_integrations' ); $enabled = self::o( 'seo_mobile_prevent_horizontal_scroll', 0 ); echo '<label><input type="checkbox" name="digitalisimo_integrations_options[seo_mobile_prevent_horizontal_scroll]" value="1" ' . checked( $enabled, 1, false ) . '> <strong>Bloquear desplazamiento horizontal accidental en móvil</strong></label><p class="description">Evita el pequeño movimiento lateral provocado por gestos diagonales en dispositivos táctiles, sin afectar el scroll vertical ni los sliders/carruseles horizontales.</p>'; submit_button( 'Guardar optimización móvil', 'primary', 'submit', false ); echo '</form><details><summary><strong>Configuración técnica avanzada</strong></summary><p><a href="' . esc_url( admin_url( 'admin.php?page=digitalisimo-seo-titles' ) ) . '">Títulos y metadatos</a> · <a href="' . esc_url( admin_url( 'admin.php?page=digitalisimo-seo-schema' ) ) . '">Schema</a> · <a href="' . esc_url( admin_url( 'admin.php?page=digitalisimo-seo-social' ) ) . '">Social</a> · <a href="' . esc_url( admin_url( 'admin.php?page=digitalisimo-seo-sitemap' ) ) . '">Sitemap</a> · <a href="' . esc_url( admin_url( 'admin.php?page=digitalisimo-seo-indexing' ) ) . '">Indexación</a></p></details>'; }
