	private static function replace( $template, $context = array() ) { $site = self::o( 'seo_site_name' ) ?: get_bloginfo( 'name' ); $repl = array( '%sitename%' => $site, '%sep%' => self::o( 'seo_separator' ) ?: '|', '%title%' => $context['title'] ?? '', '%term%' => $context['term'] ?? '', '%excerpt%' => $context['excerpt'] ?? '', '%description%' => $context['description'] ?? '', '%page%' => is_paged() ? 'Página ' . get_query_var( 'paged' ) : '' ); return trim( preg_replace( '/\s+/', ' ', strtr( (string) $template, $repl ) ) ); }
	private static function current() { if ( is_singular() ) { $id = get_queried_object_id(); $p = get_post( $id ); $type = $p ? $p->post_type : 'post'; $fallback = 'page' === $type ? 'page' : 'post'; $excerpt = $p ? wp_trim_words( wp_strip_all_tags( $p->post_content ), 30, '' ) : ''; $title = get_post_meta( $id, self::P . 'title', true ) ?: self::replace( self::o( 'seo_title_' . $fallback ), array( 'title' => get_the_title( $id ), 'excerpt' => $excerpt ) ); $description = get_post_meta( $id, self::P . 'description', true ) ?: self::replace( self::o( 'seo_description_' . $fallback ), array( 'title' => get_the_title( $id ), 'excerpt' => $excerpt ) ); $title = $title ?: get_the_title( $id ); $description = $description ?: ( $excerpt ?: get_bloginfo( 'description' ) ); return array( 'id' => $id, 'title' => $title, 'description' => $description, 'canonical' => get_post_meta( $id, self::P . 'canonical', true ) ?: get_permalink( $id ) ); } if ( is_tax() || is_category() || is_tag() ) { $t = get_queried_object(); $desc = term_description( $t ); return array( 'term' => $t, 'title' => get_term_meta( $t->term_id, self::P . 'title', true ) ?: self::replace( self::o( 'seo_title_taxonomy' ), array( 'term' => $t->name, 'description' => wp_strip_all_tags( $desc ) ) ), 'description' => get_term_meta( $t->term_id, self::P . 'description', true ) ?: self::replace( self::o( 'seo_description_taxonomy' ), array( 'term' => $t->name, 'description' => wp_strip_all_tags( $desc ) ) ), 'canonical' => get_term_link( $t ) ); } $object = get_queried_object(); $base = is_search() ? sprintf( 'Resultados para: %s', get_search_query() ) : ( is_author() && $object ? $object->display_name : ( is_post_type_archive() && $object ? $object->labels->name : get_bloginfo( 'name' ) ) ); return array( 'title' => self::replace( self::o( 'seo_title_archive' ), array( 'title' => $base ) ), 'description' => self::replace( self::o( 'seo_description_archive' ), array( 'title' => $base ) ), 'canonical' => self::canonica