	private static function should_noindex() { if ( is_search() && self::o( 'noindex_search' ) ) return true; if ( is_author() && self::o( 'noindex_authors' ) ) return true; if ( is_date() && self::o( 'noindex_date_archives' ) ) return true; if ( is_attachment() && self::o( 'noindex_attachments' ) ) return true; if ( is_singular( 'elementor_library' ) && self::o( 'noindex_elementor' ) ) return true; if ( is_tag() && self::o( 'noindex_empty_tags' ) && ! (int) get_queried_object()->count ) return true; if ( self::o( 'noindex_woo_pages' ) && ( ( function_exists( 'is_cart' ) && is_cart() ) || ( function_exists( 'is_checkout' ) && is_checkout() ) || ( function_exists( 'is_order_received_page' ) && is_order_received_page() ) ) ) return true; if ( is_singular() ) { $id = get_queried_object_id(); $legacy_robots = (array) get_post_meta( $id, self::P . 'robots', true ); if ( '1' === get_post_meta( $id, self::P . 'noindex', true ) || in_array( 'noindex', $legacy_robots, true ) ) return true; $slugs = preg_split( '/\r\n|\r|\n/', (string) self::o( 'noindex_page_slugs' ) ); $ids = array_map( 'absint', explode( ',', (string) self::o( 'noindex_page_ids' ) ) ); if ( in_array( get_post_field( 'post_name', $id ), array_map( 'sanitize_title', $slugs ), true ) || in_array( $id, $ids, true ) ) return true; } if ( ( is_tax() || is_category() || is_tag() ) && '1' === get_term_meta( get_queried_object_id(), self::P . 'noindex', true ) ) return true; return false; }
