	private static function social( $c ) { $id = $c['id'] ?? 0; $title = $id ? ( get_post_meta( $id, self::P . 'social_title', true ) ?: $c['title'] ) : $c['title']; $desc = $id ? ( get_post_meta( $id, self::P . 'social_description', true ) ?: $c['description'] ) : $c['description']; $image = $id ? ( get_post_meta( $id, self::P . 'social_image', true ) ?: get_the_post_thumbnail_url( $id, 'full' ) ) : ''; $image = $image ?: self::o( 'seo_default_image' ); echo '<meta property="og:locale" content="' . esc_attr( str_replace( '-', '_', get_locale() ) ) . '">' . "\n" . '<meta property="og:type" content="' . ( is_singular( 'post' ) ? 'article' : 'website' ) . '">' . "\n"; if ( $title ) echo '<meta property="og:title" content="' . esc_attr( wp_strip_all_tags( $title ) ) . '">' . "\n"; if ( $desc ) echo '<meta property="og:description" content="' . esc_attr( wp_strip_all_tags( $desc ) ) . '">' . "\n"; echo '<meta property="og:url" content="' . esc_url( $c['canonical'] ) . '">' . "\n" . '<meta property="og:site_name" content="' . esc_attr( self::o( 'seo_site_name' ) ?: get_bloginfo( 'name' ) ) . '">' . "\n"; if ( $image ) echo '<meta property="og:image" content="' . esc_url( $image ) . '">' . "\n"; if ( self::o( 'seo_twitter_enabled', 1 ) ) { echo '<meta name="twitter:card" content="' . esc_attr( self::o( 'seo_twitter_card' ) ?: 'summary_large_image' ) . '">' . "\n"; if ( self::o( 'seo_twitter_user' ) ) echo '<meta name="twitter:site" content="' . esc_attr( self::o( 'seo_twitter_user' ) ) . '">' . "\n"; } }
