 if ( is_array( $custom ) && ! empty( $custom['@type'] ) ) $graph[] = $custom; if ( self::o( 'seo_breadcrumbs' ) ) $graph[] = array( '@type' => 'BreadcrumbList', '@id' => $c['canonical'] . '#breadcrumb', 'itemListElement' => self::breadcrumbs( true ) ); } if ( self::o( 'seo_local_enabled' ) ) { $local = array( '@type' => self::o( 'seo_local_type' ) ?: 'LocalBusiness', '@id' => home_url( '/#localbusiness' ), 'name' => self::o( 'seo_local_name' ) ?: $org, 'telephone' => Digitalisimo_Integrations_Local_Business::phone(), 'priceRange' => self::o( 'seo_local_price_range' ), 'address' => array( '@type' => 'PostalAddress', 'streetAddress' => self::o( 'seo_local_address' ), 'addressLocality' => self::o( 'seo_local_city' ), 'addressRegion' => self::o( 'seo_local_region' ), 'postalCode' => self::o( 'seo_local_postal' ), 'addressCountry' => self::o( 'seo_local_country' ) ) ); $hours = Digitalisimo_Integrations_Local_Business::schema_hours(); if ( $hours ) $local['openingHoursSpecification'] = $hours; if ( self::o( 'seo_local_latitude' ) && self::o( 'seo_local_longitude' ) ) $local['geo'] = array( '@type' => 'GeoCoordinates', 'latitude' => self::o( 'seo_local_latitude' ), 'longitude' => self::o( 'seo_local_longitude' ) ); $graph[] = array_filter( $local ); } echo '<script type="application/ld+json">' . wp_json_encode( array( '@context' => 'https://schema.org', '@graph' => $graph ), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) . '</script>' . "\n"; }
	public static function breadcrumbs( $schema = false ) { $items = array( array( 'name' => 'Inicio', 'url' => home_url( '/' ) ) ); if ( is_singular() ) { $id = get_queried_object_id(); if ( $parent = absint( get_post_meta( $id, '_related_pillar', true ) ) ) $items[] = array( 'name' => get_the_title( $parent ), 'url' => get_permalink( $parent ) ); $items[] = array( 'name' => get_the_title( $id ), 'url' => get_permalink( $id ) ); } if ( $schema ) { $out = array(); foreach ( $items as $i => $item ) $out[] = array( '@type' => 'ListItem', 'position' => $i + 1, 'name' => $item['name'], 'item' => $item['url'] ); return $out; } return $items; }
